SET LOCAL ROLE start_catalog_owner;
SET LOCAL search_path=start_catalog,pg_catalog;
CREATE FUNCTION artist_public(key uuid) RETURNS boolean LANGUAGE sql STABLE SET search_path=pg_catalog,start_catalog AS $$ SELECT EXISTS(SELECT FROM artist WHERE id=key AND publication='published' AND review='approved' AND visibility='public') $$;
CREATE FUNCTION place_public(key uuid) RETURNS boolean LANGUAGE sql STABLE SET search_path=pg_catalog,start_catalog AS $$ SELECT EXISTS(SELECT FROM place WHERE id=key AND publication='published' AND review='approved' AND visibility='public') $$;
CREATE FUNCTION source_public(key uuid) RETURNS boolean LANGUAGE sql STABLE SET search_path=pg_catalog,start_catalog AS $$ SELECT EXISTS(SELECT FROM evidence_source WHERE id=key AND review='approved' AND visibility='public') $$;
CREATE FUNCTION source_json(key uuid) RETURNS jsonb LANGUAGE sql STABLE SET search_path=pg_catalog,start_catalog AS $$ SELECT jsonb_build_object('id',id,'sourceType',source_type,'title',public_title,'url',url,'excerpt',public_excerpt,'observedAt',to_char(observed_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'availability',availability,'lastCheckedAt',CASE WHEN last_checked_at IS NOT NULL THEN to_char(last_checked_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') END) FROM evidence_source WHERE id=key AND source_public(id) $$;
CREATE FUNCTION media_json(key uuid) RETURNS jsonb LANGUAGE sql STABLE SET search_path=pg_catalog,start_catalog AS $$ SELECT jsonb_build_object('id',id,'objectKey',object_key,'mime',mime,'width',width,'height',height) FROM media_asset WHERE id=key AND rights_state='approved' AND visibility='public' AND object_key ~ '^public/[A-Za-z0-9_./-]+$' AND position('..' IN object_key)=0 AND mime IN ('image/png','image/jpeg','image/webp') $$;
CREATE FUNCTION city_json(key uuid) RETURNS jsonb LANGUAGE sql STABLE SET search_path=pg_catalog,start_catalog AS $$ SELECT jsonb_build_object('id',id,'name',name,'countryCode',country_code) FROM city WHERE id=key $$;
CREATE FUNCTION artist_json(key uuid) RETURNS jsonb LANGUAGE sql STABLE SET search_path=pg_catalog,start_catalog AS $$ SELECT jsonb_build_object('id',id,'canonicalName',canonical_name,'artistType',artist_type,'verification',verification) FROM artist WHERE id=key AND artist_public(id) $$;
CREATE FUNCTION claim_public(key uuid) RETURNS boolean LANGUAGE sql STABLE SET search_path=pg_catalog,start_catalog AS $$
 SELECT EXISTS(SELECT FROM claim c WHERE c.id=key AND c.review='approved' AND c.visibility='public' AND NOT c.severe_dispute AND
 ((c.verification='verified' AND EXISTS(SELECT FROM claim_evidence ce WHERE ce.claim_id=c.id AND ce.support_role='supports' AND source_public(ce.evidence_source_id))) OR
 (c.verification IN ('unverified','partial','disputed') AND length(trim(coalesce(c.public_caveat,'')))>0 AND NOT (c.is_core AND c.verification='disputed')))) $$;
CREATE FUNCTION claim_json(key uuid) RETURNS jsonb LANGUAGE sql STABLE SET search_path=pg_catalog,start_catalog AS $$ SELECT jsonb_build_object('id',id,'statement',statement,'verification',verification,'verifiedAt',CASE WHEN verified_at IS NOT NULL THEN to_char(verified_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') END,'caveat',public_caveat,'sources',coalesce((SELECT jsonb_agg(source_json(evidence_source_id) ORDER BY evidence_source_id) FROM claim_evidence WHERE claim_id=c.id AND source_public(evidence_source_id)),'[]')) FROM claim c WHERE id=key AND claim_public(id) $$;
CREATE FUNCTION owner_claims(kind text,key uuid) RETURNS jsonb LANGUAGE sql STABLE SET search_path=pg_catalog,start_catalog AS $$ SELECT coalesce(jsonb_agg(claim_json(id) ORDER BY id),'[]') FROM claim WHERE claim_public(id) AND CASE kind WHEN 'relation' THEN relation_id=key WHEN 'revision' THEN revision_id=key WHEN 'stop' THEN stop_id=key WHEN 'place' THEN place_id=key WHEN 'event' THEN event_id=key ELSE false END $$;
CREATE FUNCTION owner_sources(kind text,key uuid) RETURNS jsonb LANGUAGE sql STABLE SET search_path=pg_catalog,start_catalog AS $$ SELECT coalesce(jsonb_agg(source_json(evidence_source_id) ORDER BY evidence_source_id),'[]') FROM (
 SELECT evidence_source_id FROM relation_evidence WHERE kind='relation' AND relation_id=key UNION SELECT evidence_source_id FROM revision_evidence WHERE kind='revision' AND revision_id=key UNION SELECT evidence_source_id FROM stop_evidence WHERE kind='stop' AND stop_id=key UNION SELECT evidence_source_id FROM place_evidence WHERE kind='place' AND place_id=key UNION SELECT evidence_source_id FROM event_evidence WHERE kind='event' AND event_id=key) s WHERE source_public(evidence_source_id) $$;
CREATE FUNCTION relation_public(key uuid) RETURNS boolean LANGUAGE sql STABLE SET search_path=pg_catalog,start_catalog AS $$ SELECT EXISTS(SELECT FROM artist_place_relation r WHERE r.id=key AND artist_public(r.artist_id) AND place_public(r.place_id) AND r.review='approved' AND r.visibility='public' AND NOT r.severe_dispute AND r.credible_basis AND
 ((r.verification='verified' AND (EXISTS(SELECT FROM relation_evidence e WHERE e.relation_id=r.id AND source_public(e.evidence_source_id)) OR EXISTS(SELECT FROM claim c WHERE c.relation_id=r.id AND claim_public(c.id)))) OR
 (r.verification IN ('unverified','partial') AND length(trim(coalesce(r.public_caveat,'')))>0))) $$;
CREATE FUNCTION relation_json(key uuid) RETURNS jsonb LANGUAGE sql STABLE SET search_path=pg_catalog,start_catalog AS $$ SELECT jsonb_build_object('id',id,'artist',artist_json(artist_id),'placeId',place_id,'relationType',relation_type,'explanation',explanation,'verification',verification,'caveat',public_caveat,'claims',owner_claims('relation',id),'sources',owner_sources('relation',id)) FROM artist_place_relation WHERE id=key AND relation_public(id) $$;
CREATE FUNCTION revision_safe(key uuid) RETURNS boolean LANGUAGE sql STABLE SET search_path=pg_catalog,start_catalog AS $$ SELECT EXISTS(SELECT FROM route_revision v JOIN route r ON r.id=v.route_id WHERE v.id=key AND v.review='approved' AND length(trim(v.why_worth_replicating))>0 AND length(trim(v.short_story))>0 AND (r.linked_artist_id IS NULL OR artist_public(r.linked_artist_id)) AND
 EXISTS(SELECT FROM route_stop s WHERE s.revision_id=v.id AND relation_public(s.artist_place_relation_id)) AND
 NOT EXISTS(SELECT FROM route_stop s LEFT JOIN artist_place_relation rel ON rel.id=s.artist_place_relation_id WHERE s.revision_id=v.id AND (NOT place_public(s.place_id) OR (s.artist_place_relation_id IS NOT NULL AND (NOT relation_public(rel.id) OR rel.place_id<>s.place_id OR (r.linked_artist_id IS NOT NULL AND rel.artist_id<>r.linked_artist_id))))) AND
 (SELECT max(sequence)=count(*) AND min(sequence)=1 FROM route_stop WHERE revision_id=v.id) AND
 NOT EXISTS(SELECT FROM claim c WHERE c.is_core AND (c.revision_id=v.id OR c.stop_id IN (SELECT id FROM route_stop WHERE revision_id=v.id) OR c.relation_id IN (SELECT artist_place_relation_id FROM route_stop WHERE revision_id=v.id)) AND NOT claim_public(c.id))) $$;
CREATE FUNCTION route_public(key uuid) RETURNS boolean LANGUAGE sql STABLE SET search_path=pg_catalog,start_catalog AS $$ SELECT EXISTS(SELECT FROM route r JOIN route_revision v ON v.id=r.published_revision_id AND v.route_id=r.id WHERE r.id=key AND r.publication='published' AND v.frozen_at IS NOT NULL AND v.snapshot IS NOT NULL AND revision_safe(v.id)) $$;
CREATE FUNCTION coordinates_json(p place) RETURNS jsonb LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$ SELECT CASE WHEN p.longitude IS NOT NULL THEN jsonb_build_object('longitude',p.longitude,'latitude',p.latitude,'system',p.coordinate_system) END $$;
CREATE FUNCTION stop_json(key uuid) RETURNS jsonb LANGUAGE sql STABLE SET search_path=pg_catalog,start_catalog AS $$ SELECT jsonb_build_object('id',s.id,'placeId',s.place_id,'sequence',s.sequence,'name',p.name,'address',p.address,'coordinates',coordinates_json(p),'note',s.stop_note,'stayMinutes',s.stay_minutes,'placeVerification',p.verification,'relation',relation_json(s.artist_place_relation_id),'claims',owner_claims('stop',s.id),'sources',owner_sources('stop',s.id)) FROM route_stop s JOIN place p ON p.id=s.place_id WHERE s.id=key $$;
CREATE FUNCTION build_route_snapshot(key uuid) RETURNS jsonb LANGUAGE sql STABLE SET search_path=pg_catalog,start_catalog AS $$ SELECT jsonb_build_object('type','route','id',r.id,'slug',r.slug,'revisionId',v.id,'revisionNumber',v.revision_number,'title',v.title,'hero',media_json(v.hero_media_id),'artist',artist_json(r.linked_artist_id),'city',city_json(r.city_id),'relationSummary',coalesce((SELECT string_agg(rel.explanation,'；' ORDER BY s.sequence) FROM route_stop s JOIN artist_place_relation rel ON rel.id=s.artist_place_relation_id WHERE s.revision_id=v.id),''),'whyWorthReplicating',v.why_worth_replicating,'verificationSummary',v.verification,'stopCount',(SELECT count(*) FROM route_stop WHERE revision_id=v.id),'metrics',v.metrics,'matchedReasons','[]'::jsonb,'shortStory',v.short_story,'summary',v.summary,'stops',(SELECT jsonb_agg(stop_json(id) ORDER BY sequence) FROM route_stop WHERE revision_id=v.id),'claims',owner_claims('revision',v.id),'sources',owner_sources('revision',v.id)) FROM route_revision v JOIN route r ON r.id=v.route_id WHERE v.id=key $$;
CREATE FUNCTION publish_route(key uuid) RETURNS void LANGUAGE plpgsql SET search_path=pg_catalog,start_catalog AS $$
DECLARE v route_revision; r route; snap jsonb; stamp timestamptz;
BEGIN
 SELECT rt.* INTO r FROM route rt JOIN route_revision rv ON rv.route_id=rt.id WHERE rv.id=key FOR UPDATE OF rt;
 IF NOT FOUND THEN RAISE EXCEPTION 'revision not found'; END IF;
 SELECT * INTO v FROM route_revision WHERE id=key FOR UPDATE;
 IF v.frozen_at IS NOT NULL THEN RAISE EXCEPTION 'revision already frozen'; END IF;
 IF NOT revision_safe(key) OR v.reviewer IS NULL OR v.reviewed_at IS NULL OR length(trim(coalesce(v.review_reason,'')))=0 OR NOT EXISTS(SELECT FROM review_record WHERE subject_revision_id=key AND decision='approved') THEN RAISE EXCEPTION 'revision not eligible for publication'; END IF;
 -- Lock canonical qualifications and sources before freezing, so their changes cannot race this statement.
 PERFORM p.id FROM place p JOIN route_stop s ON s.place_id=p.id WHERE s.revision_id=key ORDER BY p.id FOR SHARE OF p;
 PERFORM rel.id FROM artist_place_relation rel JOIN route_stop s ON s.artist_place_relation_id=rel.id WHERE s.revision_id=key ORDER BY rel.id FOR SHARE OF rel;
 IF NOT revision_safe(key) THEN RAISE EXCEPTION 'publication qualifications changed'; END IF;
 UPDATE route_stop s SET place_snapshot=stop_json(s.id) WHERE s.revision_id=key;
 snap=build_route_snapshot(key);stamp=clock_timestamp();snap=snap||jsonb_build_object('publishedAt',to_char(stamp AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'frozenAt',to_char(stamp AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'));
 UPDATE route_revision SET snapshot=snap,published_at=stamp,frozen_at=stamp WHERE id=key;
 UPDATE route SET published_revision_id=key,publication='published' WHERE id=r.id;
END $$;
CREATE FUNCTION publication_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,start_catalog AS $$ BEGIN IF NEW.publication='published' AND NOT EXISTS(SELECT FROM route_revision WHERE id=NEW.published_revision_id AND route_id=NEW.id AND frozen_at IS NOT NULL AND snapshot IS NOT NULL AND revision_safe(id)) THEN RAISE EXCEPTION 'route publication requires eligible frozen revision'; END IF; RETURN NEW; END $$;
CREATE TRIGGER route_publication_guard BEFORE INSERT OR UPDATE ON route FOR EACH ROW EXECUTE FUNCTION publication_guard();
-- Snapshot facts stay historical; current visibility/rights and source availability still control disclosure.
CREATE FUNCTION refresh_sources(value jsonb) RETURNS jsonb LANGUAGE sql STABLE SET search_path=pg_catalog,start_catalog AS $$ SELECT coalesce(jsonb_agg(x.value||jsonb_build_object('availability',s.availability,'lastCheckedAt',CASE WHEN s.last_checked_at IS NOT NULL THEN to_char(s.last_checked_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') END) ORDER BY x.ordinality),'[]') FROM jsonb_array_elements(coalesce(value,'[]')) WITH ORDINALITY x JOIN evidence_source s ON s.id=(x.value->>'id')::uuid WHERE source_public(s.id) $$;
CREATE FUNCTION refresh_claims(value jsonb) RETURNS jsonb LANGUAGE sql STABLE SET search_path=pg_catalog,start_catalog AS $$ SELECT coalesce(jsonb_agg(x.value||jsonb_build_object('sources',refresh_sources(x.value->'sources')) ORDER BY x.ordinality),'[]') FROM jsonb_array_elements(coalesce(value,'[]')) WITH ORDINALITY x WHERE claim_public((x.value->>'id')::uuid) $$;
CREATE FUNCTION refresh_relation(value jsonb) RETURNS jsonb LANGUAGE sql STABLE SET search_path=pg_catalog,start_catalog AS $$ SELECT CASE WHEN value IS NULL OR value='null'::jsonb OR NOT relation_public((value->>'id')::uuid) THEN NULL ELSE value||jsonb_build_object('claims',refresh_claims(value->'claims'),'sources',refresh_sources(value->'sources')) END $$;
CREATE FUNCTION snapshot_public(key uuid) RETURNS jsonb LANGUAGE sql STABLE SET search_path=pg_catalog,start_catalog AS $$ SELECT v.snapshot||jsonb_build_object('hero',media_json(v.hero_media_id),'claims',refresh_claims(v.snapshot->'claims'),'sources',refresh_sources(v.snapshot->'sources'),'stops',(SELECT jsonb_agg(x.value||jsonb_build_object('relation',refresh_relation(x.value->'relation'),'claims',refresh_claims(x.value->'claims'),'sources',refresh_sources(x.value->'sources')) ORDER BY x.ordinality) FROM jsonb_array_elements(v.snapshot->'stops') WITH ORDINALITY x)) FROM route_revision v WHERE v.id=key $$;
CREATE VIEW start_public.routes WITH (security_barrier=true) AS SELECT r.id,v.title AS name,lower(v.title) AS normalized_name,ARRAY[r.linked_artist_id]::uuid[] AS artist_ids,ARRAY[r.city_id]::uuid[] AS city_ids,(SELECT array_agg(place_id ORDER BY sequence) FROM route_stop WHERE revision_id=v.id) AS place_ids,snapshot_public(v.id)-ARRAY['shortStory','summary','publishedAt','frozenAt','stops','claims','sources'] AS data,snapshot_public(v.id) AS detail FROM route r JOIN route_revision v ON v.id=r.published_revision_id WHERE route_public(r.id);
CREATE VIEW start_public.events WITH (security_barrier=true) AS SELECT e.id,e.title AS name,e.normalized_title AS normalized_name,(SELECT coalesce(array_agg(a.artist_id ORDER BY a.artist_id),'{}') FROM event_artist a WHERE a.event_id=e.id AND artist_public(a.artist_id)) AS artist_ids,ARRAY[p.city_id]::uuid[] AS city_ids,ARRAY[p.id]::uuid[] AS place_ids,jsonb_build_object('type','event','id',e.id,'title',e.title,'artists',coalesce((SELECT jsonb_agg(artist_json(a.artist_id) ORDER BY a.artist_id) FROM event_artist a WHERE a.event_id=e.id AND artist_public(a.artist_id)),'[]'),'startsAt',to_char(e.starts_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'endsAt',CASE WHEN e.ends_at IS NOT NULL THEN to_char(e.ends_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') END,'venue',jsonb_build_object('id',p.id,'name',p.name),'city',city_json(p.city_id),'state',e.status,'publication',e.publication,'verification',e.verification,'hero',media_json(e.hero_media_id),'matchedReasons','[]'::jsonb) AS data,owner_claims('event',e.id) AS claims,owner_sources('event',e.id) AS sources FROM event e JOIN place p ON p.id=e.place_id WHERE e.publication='published' AND e.review='approved' AND e.visibility='public' AND place_public(p.id);
CREATE FUNCTION footprint_cities(key uuid) RETURNS jsonb LANGUAGE sql STABLE SET search_path=pg_catalog,start_catalog AS $$ SELECT coalesce(jsonb_agg(jsonb_build_object('city',city_json(city_id),'context','footprint','placeCount',place_count,'relations',relations) ORDER BY city_id),'[]') FROM (SELECT p.city_id,count(DISTINCT p.id) AS place_count,jsonb_agg(jsonb_build_object('id',r.id,'verification',r.verification) ORDER BY r.id) AS relations FROM artist_place_relation r JOIN place p ON p.id=r.place_id WHERE r.artist_id=key AND relation_public(r.id) GROUP BY p.city_id) c $$;
CREATE VIEW start_public.artists WITH (security_barrier=true) AS SELECT a.id,a.canonical_name AS name,a.normalized_name,ARRAY[a.id]::uuid[] AS artist_ids,coalesce((SELECT array_agg(DISTINCT city_id ORDER BY city_id) FROM (SELECT p.city_id FROM artist_place_relation rel JOIN place p ON p.id=rel.place_id WHERE rel.artist_id=a.id AND relation_public(rel.id) UNION SELECT unnest(city_ids) FROM start_public.routes WHERE a.id=ANY(artist_ids) UNION SELECT unnest(city_ids) FROM start_public.events WHERE a.id=ANY(artist_ids)) c),'{}') AS city_ids,'{}'::uuid[] AS place_ids,artist_json(a.id)||jsonb_build_object('type','artist','primaryMedia',media_json(a.primary_media_id),'footprintCities',footprint_cities(a.id),'eventCities',coalesce((SELECT jsonb_agg(city_json(city_id) ORDER BY city_id) FROM (SELECT DISTINCT unnest(city_ids) AS city_id FROM start_public.events WHERE a.id=ANY(artist_ids)) cities),'[]'),'routeCount',(SELECT count(*) FROM start_public.routes WHERE a.id=ANY(artist_ids)),'matchedReasons','[]'::jsonb) AS data FROM artist a WHERE artist_public(a.id);
CREATE VIEW start_public.places WITH (security_barrier=true) AS SELECT p.id,p.name,p.normalized_name,coalesce((SELECT array_agg(DISTINCT artist_id ORDER BY artist_id) FROM artist_place_relation WHERE place_id=p.id AND relation_public(id)),'{}') AS artist_ids,ARRAY[p.city_id]::uuid[] AS city_ids,ARRAY[p.id]::uuid[] AS place_ids,jsonb_build_object('type','place','id',p.id,'name',p.name,'city',city_json(p.city_id),'verification',p.verification,'relatedArtists',coalesce((SELECT jsonb_agg(artist_json(artist_id) ORDER BY artist_id) FROM (SELECT DISTINCT artist_id FROM artist_place_relation WHERE place_id=p.id AND relation_public(id)) a),'[]'),'topVerifiedRelation',(SELECT relation_json(id) FROM artist_place_relation WHERE place_id=p.id AND relation_public(id) AND verification='verified' ORDER BY id LIMIT 1),'relations',coalesce((SELECT jsonb_agg(relation_json(id) ORDER BY id) FROM artist_place_relation WHERE place_id=p.id AND relation_public(id)),'[]'),'relatedRouteCount',(SELECT count(*) FROM start_public.routes WHERE p.id=ANY(place_ids)),'matchedReasons','[]'::jsonb) AS data,p.address,coordinates_json(p) AS coordinates,p.practical_info,media_json(p.media_id) AS media,owner_claims('place',p.id) AS claims,owner_sources('place',p.id) AS sources FROM place p WHERE place_public(p.id);
CREATE VIEW start_public.aliases WITH (security_barrier=true) AS SELECT aa.artist_id,aa.alias,aa.normalized_alias FROM artist_alias aa WHERE artist_public(aa.artist_id);
CREATE VIEW start_public.cities WITH (security_barrier=true) AS SELECT id,name,normalized_name,country_code,city_json(id) AS data FROM city;
DO $$ DECLARE fn regprocedure; BEGIN FOR fn IN SELECT p.oid::regprocedure FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='start_catalog' LOOP EXECUTE format('ALTER FUNCTION %s SECURITY DEFINER',fn); END LOOP; END $$;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA start_catalog FROM PUBLIC,start_public_reader;
GRANT SELECT ON ALL TABLES IN SCHEMA start_public TO start_public_reader;
-- View expressions execute as invoker; expose only bounded public DTO helpers, not raw/snapshot builders or writes.
GRANT EXECUTE ON FUNCTION artist_public(uuid),place_public(uuid),source_public(uuid),source_json(uuid),media_json(uuid),city_json(uuid),artist_json(uuid),claim_public(uuid),claim_json(uuid),owner_claims(text,uuid),owner_sources(text,uuid),relation_public(uuid),relation_json(uuid),revision_safe(uuid),route_public(uuid),coordinates_json(place),refresh_sources(jsonb),refresh_claims(jsonb),refresh_relation(jsonb),snapshot_public(uuid),footprint_cities(uuid) TO start_public_reader;
RESET ROLE;
